import Mathlib

/-- A price vector for `L` commodities: a function `Fin L → ℝ` with all components strictly positive. -/
abbrev PriceVector (L : ℕ) := { p : Fin L → ℝ // ∀ l, 0 < p l }

import Mathlib

/-- The default consumption set X = ℝ₊ᴸ: all nonnegative bundles of L commodities. -/
def consumptionSet (L : ℕ) : Set (Fin L → ℝ) :=
  {x | ∀ l, 0 ≤ x l}

import Mathlib

open BigOperators Finset

def budgetHyperplane (L : ℕ) (p : Fin L → ℝ) (w : ℝ) : Set (Fin L → ℝ) :=
  {x | ∑ i, p i * x i = w}

import Mathlib

open Matrix Finset BigOperators

variable {L : ℕ}

def IsNegSemidef (M : Matrix (Fin L) (Fin L) ℝ) : Prop :=
  ∀ v : Fin L → ℝ, v ⬝ᵥ M.mulVec v ≤ 0
